import type { HTMLAttributes } from "react";
import { cx } from "../utils/cx";
import type { Tone } from "./badge";

export type AlertProps = HTMLAttributes<HTMLDivElement> & {
  tone?: Extract<Tone, "neutral" | "info" | "success" | "warning" | "danger">;
};

/**
 * An inline message that stays in the page flow: a hairline box with a toned edge. Warnings and errors use
 * `role="alert"` (announced at once); the rest use `role="status"`. Server-compatible.
 */
export function Alert({ tone = "neutral", role, className, ...rest }: AlertProps) {
  return (
    <div
      {...rest}
      role={role ?? (tone === "danger" || tone === "warning" ? "alert" : "status")}
      className={cx("hm-alert", className)}
      data-tone={tone}
    />
  );
}

export function AlertTitle({ className, ...rest }: HTMLAttributes<HTMLParagraphElement>) {
  return <p {...rest} className={cx("hm-alert-title", className)} />;
}

export function AlertDescription({ className, ...rest }: HTMLAttributes<HTMLParagraphElement>) {
  return <p {...rest} className={cx("hm-alert-description", className)} />;
}
